INSERT INTO app_check_index_info (id,reportno,customerid,customername,chineseid,chinesename,yesno,remark,inputtime,indexobject,isabnormal) VALUES (1,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D05','经营信息是否真实有效','否','经核查，企业工商登记信息与实际情况不符，存在虚报注册资本、伪造经营场所等情形，经营信息不真实。','2026-03-05 10:30:00.0','被检查人指标','是'),(2,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D31','贷款资金用途是否合规且符合合同约定','否','贷款资金未按合同约定用途使用，部分资金被挪用于购买理财产品及偿还民间借贷，违反合同约定。','2026-03-05 10:30:00.0','被检查人指标','是'),(3,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D06','总体生产经营是否正常','否','企业已处于半停产状态，主要生产线停工，订单大幅减少，生产经营不正常。','2026-03-05 10:30:00.0','被检查人指标','是'),(4,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D07','现金流是否充裕','否','企业现金流紧张，经营性现金流入不足以覆盖到期债务，存在资金链断裂风险。','2026-03-05 10:30:00.0','被检查人指标','是'),(5,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D08','所属行业、国家产业政策是否发生不利于企业的、重大变化','是','所属行业被列入国家限制类产业目录，产业政策发生重大不利变化，对企业经营产生严重影响。','2026-03-05 10:30:00.0','被检查人指标','是'),(6,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D09','环保手续是否齐全（如有）','否','企业未取得排污许可证，环保验收手续缺失，存在被环保部门处罚的风险。','2026-03-05 10:30:00.0','被检查人指标','是'),(7,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D10','纳税是否异常波动','是','企业近半年纳税额同比大幅下降，且存在欠税记录，纳税异常波动。','2026-03-05 10:30:00.0','被检查人指标','是'),(8,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D11','员工人员及工资发放是否异常波动','是','企业员工人数锐减，且存在拖欠员工工资情况，工资发放异常。','2026-03-05 10:30:00.0','被检查人指标','是'),(9,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D12','是否涉及民间融资或民间借贷担保','是','经查，企业涉及多笔民间借贷，并为关联方民间融资提供担保，金额较大。','2026-03-05 10:30:00.0','被检查人指标','是'),(10,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D13','是否涉及重大刑事案件','是','企业实际控制人因涉嫌非法吸收公众存款被立案侦查，涉及重大刑事案件。','2026-03-05 10:30:00.0','被检查人指标','是'),(11,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D14','是否向非主业盲目扩张','是','企业近年大举投资房地产、金融等非主业领域，导致主业经营受影响，存在盲目扩张。','2026-03-05 10:30:00.0','被检查人指标','是'),(12,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D15','实控人健康、家庭状况是否发生重大不利变化','是','实际控制人因重病住院，且家庭发生重大变故，对企业经营决策产生不利影响。','2026-03-05 10:30:00.0','被检查人指标','是'),(13,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D16','股权结构/管理层是否发生重大不利变化','是','企业股权结构发生重大变更，核心管理层集体离职，管理层动荡。','2026-03-05 10:30:00.0','被检查人指标','是'),(14,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D17','是否遭受重大自然灾害等不可抗力的负面影响','是','企业厂房遭受火灾，生产设备损毁严重，恢复生产需较长时间。','2026-03-05 10:30:00.0','被检查人指标','是'),(15,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D18','是否达到相关办法中规定的业务中止或退出规定','是','企业已触发相关办法中规定的业务中止条件，如连续逾期超过90天。','2026-03-05 10:30:00.0','被检查人指标','是'),(16,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D19','还款意愿是否下降','是','借款人多次拖延还款，沟通中表现出消极还款意愿，还款意愿明显下降。','2026-03-05 10:30:00.0','被检查人指标','是'),(17,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D22','担保能力是否下降','是','担保人对外担保金额过大，代偿能力不足，担保能力显著下降。','2026-03-05 10:30:00.0','担保人指标','是'),(18,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D23','还款意愿是否下降','是','担保人拒绝配合贷后检查，且明确表示不愿承担担保责任，还款意愿下降。','2026-03-05 10:30:00.0','担保人指标','是'),(19,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D24','抵/质押物是否被查封、被冻或冻结','是','抵/质押物已被法院查封，存在被处置的风险。','2026-03-05 10:30:00.0','抵质押物指标','是'),(20,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D25','抵/质押物权属是否变更或发生争议','是','抵/质押物权属发生变更，且存在第三方主张权利，权属争议较大。','2026-03-05 10:30:00.0','抵质押物指标','是'),(21,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D26','抵/质押物是否被毁损','是','抵/质押物因保管不善发生严重毁损，价值大幅贬损。','2026-03-05 10:30:00.0','抵质押物指标','是'),(22,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D27','抵/质押物市场价值是否大幅下降','是','抵/质押物市场价格大幅下跌，当前市值已不足以覆盖贷款本息。','2026-03-05 10:30:00.0','抵质押物指标','是'),(23,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D28','抵/质押物状态（使用情况、租赁关系等）是否发生、变化','是','/','2026-03-05 10:30:00.0','抵质押物指标','是'),(24,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D29','第三方保管的，抵/质押物保管状态是否异常（如、有）','否','/','2026-03-05 10:30:00.0','抵质押物指标','否'),(25,'RPT-202603-001','CUST-001','苏州XX精密机械制造有限公司','D30','第三方保管的，保管人的保管能力及资质是否发、生变化（如有）','否','/','2026-03-05 10:30:00.0','抵质押物指标','否');

